// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title SnarkConstants
/// @notice This contract contains constants related to the SNARK
/// components of MACI.
contract SnarkConstants {
  /// @notice The scalar field
  uint256 internal constant SNARK_SCALAR_FIELD =
    21888242871839275222246405745257275088548364400416034343698204186575808495617;

  /// @notice The public key here is the first Pedersen base
  /// point from iden3's circomlib implementation of the Pedersen hash.
  /// Since it is generated using a hash-to-curve function, we are
  /// confident that no-one knows the private key associated with this
  /// public key. See:
  /// https://github.com/iden3/circomlib/blob/d5ed1c3ce4ca137a6b3ca48bec4ac12c1b38957a/src/pedersen_printbases.js
  uint256 internal constant PAD_PUBLIC_KEY_X =
    10457101036533406547632367118273992217979173478358440826365724437999023779287;
  uint256 internal constant PAD_PUBLIC_KEY_Y =
    19824078218392094440610104313265183977899662750282163392862422243483260492317;

  /// @notice The Keccack256 hash of 'Maci'
  uint256 internal constant NOTHING_UP_MY_SLEEVE =
    8370432830353022751713833565135785980866757267633941821328460903436894336785;
}

contracts/crypto/Verifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Pairing } from "./Pairing.sol";
import { SnarkConstants } from "./SnarkConstants.sol";
import { SnarkCommon } from "./SnarkCommon.sol";
import { IVerifier } from "../interfaces/IVerifier.sol";

/// @title Verifier
/// @notice a Groth16 verifier contract
contract Verifier is IVerifier, SnarkConstants, SnarkCommon {
  struct Proof {
    Pairing.G1Point a;
    Pairing.G2Point b;
    Pairing.G1Point c;
  }

  using Pairing for *;

  uint256 public constant PRIME_Q = 21888242871839275222246405745257275088696311157297823662689037894645226208583;

  /// @notice custom errors
  error InvalidProofQ();
  error InvalidInputVal();

  /// @notice Verify a zk-SNARK proof
  /// @param _proof The proof
  /// @param verifyingKey The verifying key
  /// @param inputs The public inputs to the circuit
  /// @return isValid Whether the proof is valid given the verifying key and public
  ///          input. Note that this function only supports one public input.
  ///          Refer to the Semaphore source code for a verifier that supports
  ///          multiple public inputs.
  function verify(
    uint256[8] memory _proof,
    VerifyingKey memory verifyingKey,
    uint256[] calldata inputs
  ) public view override returns (bool isValid) {
    Proof memory proof;
    proof.a = Pairing.G1Point(_proof[0], _proof[1]);
    proof.b = Pairing.G2Point([_proof[2], _proof[3]], [_proof[4], _proof[5]]);
    proof.c = Pairing.G1Point(_proof[6], _proof[7]);

    // Make sure that proof.A, B, and C are each less than the prime q
    checkPoint(proof.a.x);
    checkPoint(proof.a.y);
    checkPoint(proof.b.x[0]);
    checkPoint(proof.b.y[0]);
    checkPoint(proof.b.x[1]);
    checkPoint(proof.b.y[1]);
    checkPoint(proof.c.x);
    checkPoint(proof.c.y);

    // Compute the linear combination verifying key X
    Pairing.G1Point memory x = Pairing.G1Point(0, 0);

    uint256 inputsLength = inputs.length;

    for (uint256 i = 0; i < inputsLength; ) {
      uint256 input = inputs[i];

      // Make sure that the input is less than the snark scalar field
      if (input >= SNARK_SCALAR_FIELD) {
        revert InvalidInputVal();
      }

      x = Pairing.plus(x, Pairing.scalarMul(verifyingKey.ic[i + 1], input));

      unchecked {
        i++;
      }
    }

    x = Pairing.plus(x, verifyingKey.ic[0]);

    isValid = Pairing.pairing(
      Pairing.negate(proof.a),
      proof.b,
      verifyingKey.alpha1,
      verifyingKey.beta2,
      x,
      verifyingKey.gamma2,
      proof.c,
      verifyingKey.delta2
    );
  }

  function checkPoint(uint256 point) internal pure {
    if (point >= PRIME_Q) {
      revert InvalidProofQ();
    }
  }
}

contracts/extensions/eip712/EIP712Signup.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import { EIP712 } from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title EIP712SignupChecker
 * @notice EIP-712 signature verification for MACI signup
 * @dev Implements the Excubiae Checker pattern for signature verification
 */
contract EIP712SignupChecker is EIP712, Ownable {
    using ECDSA for bytes32;

    // ============ State Variables ============

    /// @notice Mapping of user address to nonce (anti-replay)
    mapping(address => uint256) public nonces;

    /// @notice Mapping of user address to signup status (anti-double-signup)
    mapping(address => bool) public hasSignedUp;

    /// @notice Set of allowed relayer addresses
    mapping(address => bool) public relayers;

    // ============ EIP-712 Type Hash ============

    /// @notice Type hash for SignupRequest
    bytes32 public constant SIGNUP_REQUEST_TYPEHASH = 
        keccak256("SignupRequest(address subject,uint256 nonce,uint256 deadline)");

    // ============ Events ============

    event SignupChecked(address indexed subject, uint256 nonce, uint256 timestamp);
    event RelayerUpdated(address indexed relayer, bool status);

    // ============ Errors ============

    error InvalidSignature();
    error SignatureExpired();
    error InvalidNonce();
    error AlreadySignedUp();
    error NotRelayer();

    // ============ Constructor ============

    /**
     * @notice Initialize the checker
     * @param _name EIP-712 domain name
     * @param _version EIP-712 domain version
     */
    constructor(
        string memory _name,
        string memory _version
    ) EIP712(_name, _version) Ownable(msg.sender) {
        relayers[msg.sender] = true;
    }

    // ============ Checker Function ============

    /**
     * @notice Check if a signup request is valid
     * @dev Called by the policy contract
     * @param _subject The user address to check
     * @param _evidence Encoded signature data (signature, deadline)
     * @return valid Whether the signature is valid
     */
    function check(address _subject, bytes calldata _evidence) external returns (bool valid) {
        // Decode evidence: (signature, deadline)
        (bytes memory signature, uint256 deadline) = abi.decode(_evidence, (bytes, uint256));

        // 1. Check deadline
        if (block.timestamp > deadline) revert SignatureExpired();

        // 2. Check not already signed up
        if (hasSignedUp[_subject]) revert AlreadySignedUp();

        // 3. Get expected nonce
        uint256 expectedNonce = nonces[_subject];

        // 4. Reconstruct and verify signature
        bytes32 structHash = keccak256(
            abi.encode(SIGNUP_REQUEST_TYPEHASH, _subject, expectedNonce, deadline)
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address signer = ECDSA.recover(digest, signature);

        // 5. Verify signer matches subject
        if (signer != _subject) revert InvalidSignature();

        // 6. Update state (CEI pattern - but this is a check, state updated in policy)
        // Note: State updates moved to markSignedUp() to be called after MACI signup succeeds
        
        emit SignupChecked(_subject, expectedNonce, block.timestamp);

        return true;
    }

    /**
     * @notice Mark a user as signed up (called by policy after successful MACI signup)
     * @param _subject The user address
     */
    function markSignedUp(address _subject) external {
        // Only callable by owner (policy contract should be set as owner or use access control)
        require(msg.sender == owner() || relayers[msg.sender], "Not authorized");
        
        nonces[_subject]++;
        hasSignedUp[_subject] = true;
    }

    // ============ View Functions ============

    /**
     * @notice Get nonce for a user
     */
    function getNonce(address _user) external view returns (uint256) {
        return nonces[_user];
    }

    /**
     * @notice Check if user has signed up
     */
    function isSignedUp(address _user) external view returns (bool) {
        return hasSignedUp[_user];
    }

    /**
     * @notice Get the EIP-712 domain separator
     */
    function getDomainSeparator() external view returns (bytes32) {
        return _domainSeparatorV4();
    }

    // ============ Admin Functions ============

    /**
     * @notice Update relayer status
     */
    function setRelayer(address _relayer, bool _status) external onlyOwner {
        relayers[_relayer] = _status;
        emit RelayerUpdated(_relayer, _status);
    }
}

