pragma solidity ^0.8.28;

import { SnarkCommon } from "../crypto/SnarkCommon.sol";
import { DomainObjs } from "../utilities/DomainObjs.sol";

/// @title IVerifyingKeysRegistry
/// @notice VerifyingKeysRegistry interface
interface IVerifyingKeysRegistry {
  struct SetVerifyingKeysBatchArgs {
    /// @param stateTreeDepth The state tree depth
    uint256 stateTreeDepth;
    /// @param pollStateTreeDepth The poll state tree depth
    uint256 pollStateTreeDepth;
    /// @param tallyProcessingStateTreeDepth The intermediate state tree depth
    uint256 tallyProcessingStateTreeDepth;
    /// @param voteOptionTreeDepth The vote option tree depth
    uint256 voteOptionTreeDepth;
    /// @param messageBatchSize The message batch size
    uint8 messageBatchSize;
    /// @param modes Array of QV, Non-QV or Full modes (must have the same length as process and tally keys)
    DomainObjs.Mode[] modes;
    /// @param pollJoiningVerifyingKey The poll joining verifying key
    SnarkCommon.VerifyingKey pollJoiningVerifyingKey;
    /// @param pollJoinedVerifyingKey The poll joined verifying key
    SnarkCommon.VerifyingKey pollJoinedVerifyingKey;
    /// @param processVerifyingKeys The process verifying keys (must have the same length as modes)
    SnarkCommon.VerifyingKey[] processVerifyingKeys;
    /// @param tallyVerifyingKeys The tally verifying keys (must have the same length as modes)
    SnarkCommon.VerifyingKey[] tallyVerifyingKeys;
  }

  /// @notice Get the tally verifying key
  /// @param _stateTreeDepth The state tree depth
  /// @param _intStateTreeDepth The intermediate state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _mode QV, Non-QV, Full
  /// @return The verifying key
  function getTallyVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _intStateTreeDepth,
    uint256 _voteOptionTreeDepth,
    DomainObjs.Mode _mode
  ) external view returns (SnarkCommon.VerifyingKey memory);

  /// @notice Get the process verifying key
  /// @param _stateTreeDepth The state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _messageBatchSize The message batch size
  /// @param _mode QV, Non-QV, Full
  /// @return The verifying key
  function getProcessVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _voteOptionTreeDepth,
    uint8 _messageBatchSize,
    DomainObjs.Mode _mode
  ) external view returns (SnarkCommon.VerifyingKey memory);

  /// @notice Get the poll joining verifying key
  /// @param _stateTreeDepth The state tree depth
  /// @return The verifying key
  function getPollJoiningVerifyingKey(uint256 _stateTreeDepth) external view returns (SnarkCommon.VerifyingKey memory);

  /// @notice Get the poll joined verifying key
  /// @param _stateTreeDepth The state tree depth
  /// @return The verifying key
  function getPollJoinedVerifyingKey(uint256 _stateTreeDepth) external view returns (SnarkCommon.VerifyingKey memory);
}

contracts/MACI.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IBasePolicy } from "@excubiae/contracts/contracts/interfaces/IBasePolicy.sol";

import { IPollFactory } from "./interfaces/IPollFactory.sol";
import { IMessageProcessorFactory } from "./interfaces/IMessageProcessorFactory.sol";
import { ITallyFactory } from "./interfaces/ITallyFactory.sol";
import { IVerifier } from "./interfaces/IVerifier.sol";
import { IVerifyingKeysRegistry } from "./interfaces/IVerifyingKeysRegistry.sol";
import { IInitialVoiceCreditProxy } from "./interfaces/IInitialVoiceCreditProxy.sol";
import { IMACI } from "./interfaces/IMACI.sol";
import { Params } from "./utilities/Params.sol";
import { DomainObjs } from "./utilities/DomainObjs.sol";
import { CurveBabyJubJub } from "./crypto/BabyJubJub.sol";
import { Hasher } from "./crypto/Hasher.sol";
import { InternalLeanIMT, LeanIMTData } from "./trees/LeanIMT.sol";

/// @title MACI - Minimum Anti-Collusion Infrastructure Version 1
/// @notice A contract which allows users to sign up, and deploy new polls
contract MACI is IMACI, DomainObjs, Params, Hasher {
  /// @notice The state tree depth is fixed. As such it should be as large as feasible
  /// so that there can be as many users as possible.  i.e. 2 ** 23 = 8388608
  /// this should also match the parameter of the circom circuits.
  /// @notice IMPORTANT: remember to change the ballot tree depth
  /// in contracts/ts/generateEmptyBallotRoots.ts file
  /// if we change the state tree depth!
  uint8 public immutable stateTreeDepth;

  uint256 public immutable maxSignups;

  uint8 internal constant STATE_TREE_ARITY = 2;

  /// @notice This is the poseidon hash of the pad key
  uint256 internal constant PAD_KEY_HASH = 1309255631273308531193241901289907343161346846555918942743921933037802809814;

  /// @notice The roots of the empty ballot trees
  uint256[5] public emptyBallotRoots;

  /// @notice Each poll has an incrementing ID
  uint256 public nextPollId;

  /// @notice A mapping of poll IDs to Poll contracts.
  mapping(uint256 => PollContracts) public polls;

  /// @notice Factory contract that deploy a Poll contract
  IPollFactory public immutable pollFactory;

  /// @notice Factory contract that deploy a MessageProcessor contract
  IMessageProcessorFactory public immutable messageProcessorFactory;

  /// @notice Factory contract that deploy a Tally contract
  ITallyFactory public immutable tallyFactory;

  /// @notice The state tree. Stores users' public keys
  LeanIMTData public leanIMTData;

  /// @notice Address of the signup policy, a contract which determines whether a
  /// user may sign up to vote
  IBasePolicy public immutable signUpPolicy;

  /// @notice The verifier contract for zk-SNARK proofs
  /// This is send to the poll when deploying
  IVerifier public immutable verifier;

  /// @notice The verifying keys registry contract
  /// This is send to the poll when deploying
  IVerifyingKeysRegistry public immutable verifyingKeysRegistry;

  /// @notice The array of the state tree roots for each sign up
  /// For the N'th sign up, the state tree root will be stored at the index N
  uint256[] public stateRootsOnSignUp;

  struct InitParams {
    // The PollFactory contract
    IPollFactory pollFactory;
    // The MessageProcessorFactory contract
    IMessageProcessorFactory messageProcessorFactory;
    // The TallyFactory contract
    ITallyFactory tallyFactory;
    // MACI signup policy contract
    IBasePolicy signUpPolicy;
    // Verifier contract for zk-SNARK proofs
    IVerifier verifier;
    // Verifying keys registry contract for zk-SNARK proofs
    IVerifyingKeysRegistry verifyingKeysRegistry;
    // Depth of the state tree
    uint8 stateTreeDepth;
    // Roots of the empty ballot trees
    uint256[5] emptyBallotRoots;
  }

  // Events
  event SignUp(
    uint256 _stateIndex,
    uint256 _timestamp,
    uint256 indexed _userPublicKeyX,
    uint256 indexed _userPublicKeyY
  );
  event DeployPoll(
    uint256 _pollId,
    uint256 indexed _coordinatorPublicKeyX,
    uint256 indexed _coordinatorPublicKeyY,
    Mode _mode
  );

  /// @notice custom errors
  error PoseidonHashLibrariesNotLinked();
  error TooManySignups();
  error InvalidPublicKey();
  error PollDoesNotExist(uint256 pollId);
  error UserNotSignedUp();

  /// @notice Create a new instance of the MACI contract.
  /// @param initParams The initialization parameters defined above
  constructor(InitParams memory initParams) payable {
    // initialize and insert the blank leaf
    InternalLeanIMT._insert(leanIMTData, PAD_KEY_HASH);
    stateRootsOnSignUp.push(PAD_KEY_HASH);

    pollFactory = initParams.pollFactory;
    messageProcessorFactory = initParams.messageProcessorFactory;
    tallyFactory = initParams.tallyFactory;
    signUpPolicy = initParams.signUpPolicy;
    verifier = initParams.verifier;
    verifyingKeysRegistry = initParams.verifyingKeysRegistry;
    stateTreeDepth = initParams.stateTreeDepth;
    maxSignups = uint256(STATE_TREE_ARITY) ** uint256(initParams.stateTreeDepth);
    emptyBallotRoots = initParams.emptyBallotRoots;

    // Verify linked poseidon libraries
    if (hash2([uint256(1), uint256(1)]) == 0) revert PoseidonHashLibrariesNotLinked();
  }

  /// @inheritdoc IMACI
  function signUp(PublicKey memory _publicKey, bytes memory _signUpPolicyData) public virtual {
    // ensure we do not have more signups than what the circuits support
    if (leanIMTData.size >= maxSignups) revert TooManySignups();

    // ensure that the public key is on the baby jubjub curve
    if (!CurveBabyJubJub.isOnCurve(_publicKey.x, _publicKey.y)) {
      revert InvalidPublicKey();
    }

    // Register the user via the sign-up policy. This function should
    // throw if the user has already registered or if ineligible to do so.
    signUpPolicy.enforce(msg.sender, _signUpPolicyData);

    // Hash the public key and insert it into the tree.
    uint256 publicKeyHash = hashLeftRight(_publicKey.x, _publicKey.y);
    uint256 stateRoot = InternalLeanIMT._insert(leanIMTData, publicKeyHash);

    // Store the current state tree root in the array
    stateRootsOnSignUp.push(stateRoot);

    emit SignUp(leanIMTData.size - 1, block.timestamp, _publicKey.x, _publicKey.y);
  }

  /// @inheritdoc IMACI
  function deployPoll(DeployPollArgs memory args) public virtual returns (PollContracts memory) {
    // cache the poll to a local variable so we can increment it
    uint256 pollId = nextPollId;

    // Increment the poll ID for the next poll
    // 2 ** 256 polls available
    unchecked {
      nextPollId++;
    }

    // check coordinator key is a valid point on the curve
    if (!CurveBabyJubJub.isOnCurve(args.coordinatorPublicKey.x, args.coordinatorPublicKey.y)) {
      revert InvalidPublicKey();
    }

    ExtContracts memory extContracts = ExtContracts({
      maci: IMACI(address(this)),
      verifier: verifier,
      verifyingKeysRegistry: verifyingKeysRegistry,
      policy: IBasePolicy(args.policy),
      initialVoiceCreditProxy: IInitialVoiceCreditProxy(args.initialVoiceCreditProxy)
    });

    IPollFactory.DeployPollArgs memory deployPollArgs = IPollFactory.DeployPollArgs({
      startDate: args.startDate,
      endDate: args.endDate,
      treeDepths: args.treeDepths,
      messageBatchSize: args.messageBatchSize,
      coordinatorPublicKey: args.coordinatorPublicKey,
      extContracts: extContracts,
      emptyBallotRoot: emptyBallotRoots[args.treeDepths.voteOptionTreeDepth - 1],
      pollId: pollId,
      relayers: args.relayers,
      voteOptions: args.voteOptions
    });

    address poll = pollFactory.deploy(deployPollArgs);
    address messageProcessor = messageProcessorFactory.deploy(
      address(verifier),
      address(verifyingKeysRegistry),
      poll,
      args.mode
    );
    address tally = tallyFactory.deploy(
      address(verifier),
      address(verifyingKeysRegistry),
      poll,
      messageProcessor,
      args.mode
    );

    // store the addresses in a struct so they can be returned
    PollContracts memory pollAddresses = PollContracts({
      poll: poll,
      messageProcessor: messageProcessor,
      tally: tally
    });

    polls[pollId] = pollAddresses;

    emit DeployPoll(pollId, args.coordinatorPublicKey.x, args.coordinatorPublicKey.y, args.mode);

    return pollAddresses;
  }

  /// @inheritdoc IMACI
  function getStateTreeRoot() public view returns (uint256 root) {
    root = InternalLeanIMT._root(leanIMTData);
  }

  /// @notice Get the Poll details
  /// @param _pollId The identifier of the Poll to retrieve
  /// @return pollContracts The Poll contract object
  function getPoll(uint256 _pollId) public view returns (PollContracts memory pollContracts) {
    if (_pollId >= nextPollId) revert PollDoesNotExist(_pollId);
    pollContracts = polls[_pollId];
  }

  /// @inheritdoc IMACI
  function totalSignups() public view returns (uint256 signUps) {
    signUps = leanIMTData.size;
  }

  /// @inheritdoc IMACI
  function getStateRootOnIndexedSignUp(uint256 _index) external view returns (uint256 stateRoot) {
    stateRoot = stateRootsOnSignUp[_index];
  }

  /// @inheritdoc IMACI
  function getStateIndex(uint256 _publicKeyHash) external view returns (uint256) {
    uint256 index = leanIMTData.leaves[_publicKeyHash];

    if (index == 0) revert UserNotSignedUp();

    // need to subtract 1 because the index is 1 indexed due to 0 index reserved for deleted leaves
    return index - 1;
  }
}

contracts/MessageProcessor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Clone } from "@excubiae/contracts/contracts/proxy/Clone.sol";

import { IMACI } from "./interfaces/IMACI.sol";
import { IPoll } from "./interfaces/IPoll.sol";
import { SnarkCommon } from "./crypto/SnarkCommon.sol";
import { Hasher } from "./crypto/Hasher.sol";
import { IVerifier } from "./interfaces/IVerifier.sol";
import { IVerifyingKeysRegistry } from "./interfaces/IVerifyingKeysRegistry.sol";
import { IMessageProcessor } from "./interfaces/IMessageProcessor.sol";
import { DomainObjs } from "./utilities/DomainObjs.sol";

/// @title MessageProcessor
/// @dev MessageProcessor is used to process messages published by signup users.
/// It will process message by batch due to large size of messages.
/// After it finishes processing, the sbCommitment will be used for Tally and Subsidy contracts.
contract MessageProcessor is Clone, SnarkCommon, Hasher, IMessageProcessor, DomainObjs {
  /// @notice custom errors
  error NoMoreMessages();
  error StateNotMerged();
  error InvalidProcessMessageProof();
  error totalSignupsTooLarge();
  error CurrentMessageBatchIndexTooLarge();
  error BatchEndIndexTooLarge();

  /// @inheritdoc IMessageProcessor
  bool public processingComplete;

  /// @notice  The number of batches processed
  uint256 public totalBatchesProcessed;

  /// @notice The current message batch index
  uint256 public currentBatchIndex;

  /// @inheritdoc IMessageProcessor
  uint256 public sbCommitment;

  IPoll public poll;
  IVerifier public verifier;
  IVerifyingKeysRegistry public verifyingKeysRegistry;
  Mode public mode;

  /// @notice Initializes the contract.
  function _initialize() internal override {
    super._initialize();

    bytes memory data = _getAppendedBytes();
    (address _verifier, address _verifyingKeysRegistry, address _poll, Mode _mode) = abi.decode(
      data,
      (address, address, address, Mode)
    );

    verifier = IVerifier(_verifier);
    verifyingKeysRegistry = IVerifyingKeysRegistry(_verifyingKeysRegistry);
    poll = IPoll(_poll);
    mode = _mode;
    currentBatchIndex = 1;
  }

  /// @notice Update the Poll's currentSbCommitment if the proof is valid.
  /// @param _newSbCommitment The new state root and ballot root commitment
  ///                         after all messages are processed
  /// @param _proof The zk-SNARK proof
  function processMessages(uint256 _newSbCommitment, uint256[8] calldata _proof) external {
    // There must be unprocessed messages
    if (processingComplete) {
      revert NoMoreMessages();
    }

    (, uint8 voteOptionTreeDepth, ) = poll.treeDepths();
    uint8 messageBatchSize = poll.messageBatchSize();

    uint256[] memory batchHashes;
    // Copy the state and ballot commitment and set the batch index if this
    // is the first batch to process
    if (totalBatchesProcessed == 0) {
      uint256 currentSbCommitment = poll.currentSbCommitment();
      sbCommitment = currentSbCommitment;

      /// @notice this also checks that the voting period is over so we do not
      /// need to check it in this function
      poll.padLastBatch();
      batchHashes = poll.getBatchHashes();
      currentBatchIndex = batchHashes.length - 1;
    } else {
      batchHashes = poll.getBatchHashes();
    }

    uint256 outputBatchHash = batchHashes[currentBatchIndex];

    if (
      !verifyProcessProof(
        currentBatchIndex,
        outputBatchHash,
        _newSbCommitment,
        messageBatchSize,
        voteOptionTreeDepth,
        _proof
      )
    ) {
      revert InvalidProcessMessageProof();
    }

    (, uint256 numMessages) = poll.totalSignupsAndMessages();

    updateMessageProcessingData(_newSbCommitment, numMessages <= messageBatchSize * (totalBatchesProcessed + 1));
  }

  /// @inheritdoc IMessageProcessor
  function getPublicCircuitInputs(
    uint256 _currentMessageBatchIndex,
    uint256 _newSbCommitment,
    uint256 _outputBatchHash
  ) public view override returns (uint256[] memory publicInputs) {
    uint256 coordinatorPublicKeyHash = poll.coordinatorPublicKeyHash();
    uint8 messageBatchSize = poll.messageBatchSize();
    (uint256 totalSignups, uint256 numMessages) = poll.totalSignupsAndMessages();
    uint256 batchEndIndex = _currentMessageBatchIndex * messageBatchSize;

    if (batchEndIndex > numMessages) {
      batchEndIndex = numMessages;
    }

    uint256 batchStartIndex = _currentMessageBatchIndex > 0 ? (_currentMessageBatchIndex - 1) * messageBatchSize : 0;

    publicInputs = new uint256[](9);
    publicInputs[0] = totalSignups;
    publicInputs[1] = _outputBatchHash;
    publicInputs[2] = poll.actualStateTreeDepth();
    publicInputs[3] = coordinatorPublicKeyHash;
    publicInputs[4] = poll.voteOptions();
    publicInputs[5] = (sbCommitment == 0 ? poll.currentSbCommitment() : sbCommitment);
    publicInputs[6] = _newSbCommitment;
    publicInputs[7] = batchStartIndex;
    publicInputs[8] = batchEndIndex;
  }

  /// @notice Verify the proof for processMessage
  /// @dev used to update the sbCommitment
  /// @param _currentBatchIndex The batch index of current message batch
  /// @param _outputBatchHash The output batch hash
  /// @param _newSbCommitment The new sbCommitment after we update this message batch
  /// @param _messageBatchSize The message batch size
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _proof The zk-SNARK proof
  /// @return isValid Whether the proof is valid
  function verifyProcessProof(
    uint256 _currentBatchIndex,
    uint256 _outputBatchHash,
    uint256 _newSbCommitment,
    uint8 _messageBatchSize,
    uint8 _voteOptionTreeDepth,
    uint256[8] memory _proof
  ) internal view returns (bool isValid) {
    // get the tree depths
    // get the message batch size from the message tree subdepth
    // get the number of signups
    IMACI maci = poll.getMaciContract();

    uint256[] memory publicCircuitInputs = getPublicCircuitInputs(
      _currentBatchIndex,
      _newSbCommitment,
      _outputBatchHash
    );

    // Get the verifying key from the VerifyingKeysRegistry
    VerifyingKey memory verifyingKey = verifyingKeysRegistry.getProcessVerifyingKey(
      maci.stateTreeDepth(),
      _voteOptionTreeDepth,
      _messageBatchSize,
      mode
    );

    isValid = verifier.verify(_proof, verifyingKey, publicCircuitInputs);
  }

  /// @notice update message processing state variables
  /// @param _newSbCommitment sbCommitment to be updated
  /// @param _processingComplete update flag that indicate processing is finished or not
  function updateMessageProcessingData(uint256 _newSbCommitment, bool _processingComplete) internal {
    sbCommitment = _newSbCommitment;
    processingComplete = _processingComplete;
    currentBatchIndex -= 1;
    totalBatchesProcessed++;
  }
}

