// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { PoseidonT3 } from "../crypto/PoseidonT3.sol";

/// @notice A struct that holds a LazyIMT data
struct LazyIMTData {
  uint40 maxIndex;
  uint40 numberOfLeaves;
  mapping(uint256 => uint256) elements;
}

/// @notice Custom errors
error DefaultZeroBadIndex();
error DepthTooLarge();
error DepthCannotBeZero();
error NumberOfLeavesCannotBeZero();
error AmbiguousDepth();

/// @title InternalLazyIMT
/// @dev A LazyIMT with Zeroes value set to the hash of
/// a MACI Blank State Leaf
/// @notice This implementation is taken from zk-kit
/// https://github.com/privacy-scaling-explorations/zk-kit/blob/main/packages/imt.sol
/// and modified to work with MACI.
library InternalLazyIMT {
  uint256 internal constant MAX_DEPTH = 32;

  uint40 internal constant MAX_INDEX = (1 << 32) - 1;

  uint256 internal constant Z_0 = 11672248758340751985123309654953904206381780234474872690580702076708041504880;
  uint256 internal constant Z_1 = 19331652342509548919759736046837708337654745411782648764289887782687120014303;
  uint256 internal constant Z_2 = 18519476485775495785243637794680967176074958346742730499486256277910758615950;
  uint256 internal constant Z_3 = 9253233849380840352686159591459001593974324654530951637356937482726051049955;
  uint256 internal constant Z_4 = 10008057475275407721464510218327511033274186183546595274082294419551333876278;
  uint256 internal constant Z_5 = 15276174844323421024329399066736221296663144569254850535842419823050726099024;
  uint256 internal constant Z_6 = 1663370527555021269392314605382694643870089495718054678084009438746272917438;
  uint256 internal constant Z_7 = 5399301852449787938729592959767758598837764764280654401872291245798482437544;
  uint256 internal constant Z_8 = 4866075081400981690778814020960726840573964310176395723518004517625390292575;
  uint256 internal constant Z_9 = 21512971799783438919165771504125986132021995840913348675037432712428503908741;
  uint256 internal constant Z_10 = 6813201029531886832110450552606730226830795691661971814974043269824622075721;
  uint256 internal constant Z_11 = 4282197328275431102793102423164292973246002971886176475154495114411725560932;
  uint256 internal constant Z_12 = 4474097095427155576994331666490221311906734708164928024389577211354798674284;
  uint256 internal constant Z_13 = 16303501423444667524550016135096177645956734575071733778212692442175638800868;
  uint256 internal constant Z_14 = 11834883125877480658180154495924219797246595906174241554714912178063903473495;
  uint256 internal constant Z_15 = 21752763454383755716790608888286452627387137767804799155682605808857836412055;
  uint256 internal constant Z_16 = 5878491137934378204024001705840900760190921316730664578336270829522539347503;
  uint256 internal constant Z_17 = 5014169026659671119884698238031833512856466216917734960735991065161008496132;
  uint256 internal constant Z_18 = 19311600495894300621072958324859482654455117060885576559343547805624725018136;
  uint256 internal constant Z_19 = 15368932622333818975708067041455298688523851424706672901025003972939725872614;
  uint256 internal constant Z_20 = 5036099980660379136110597812587879597471706149812314478284605042832832209846;
  uint256 internal constant Z_21 = 13357394670026084987191778289003504081004998235964966603087766793745546987193;
  uint256 internal constant Z_22 = 10438489465213364257193984932323726432391881657287944078083426815937403593118;
  uint256 internal constant Z_23 = 7249486105363175453605253492686896570526177409238866753310555472228694202538;
  uint256 internal constant Z_24 = 3655860097030420750733077755877709404735101461268298220597674245871361918711;
  uint256 internal constant Z_25 = 8513603446469303221334237659899242027113512772967711874924053158098904862108;
  uint256 internal constant Z_26 = 20090988852621915117779997764070319964153217931865684414898070571363916272441;
  uint256 internal constant Z_27 = 10793812588625892452403148694406198611998933881740947225990083504329635168286;
  uint256 internal constant Z_28 = 16378705679850173561776752226215101393834638101684915380663369948813310285412;
  uint256 internal constant Z_29 = 3171958789403408022771249347350805982761602523060076841322587336513700629277;
  uint256 internal constant Z_30 = 4317066530930547221334165656982465935294601583223716527310928098276220702182;
  uint256 internal constant Z_31 = 10941045499345182703430039707419795077832259731433536712773883025687941209296;
  uint256 internal constant Z_32 = 7782953605310617292941028720001655024539110273642468830753550483253450421111;

  /// @notice Returns the default zero value for a given index
  /// @param index The index of the zero value
  /// @return The zero value
  function _defaultZero(uint8 index) internal pure returns (uint256) {
    if (index == 0) return Z_0;
    if (index == 1) return Z_1;
    if (index == 2) return Z_2;
    if (index == 3) return Z_3;
    if (index == 4) return Z_4;
    if (index == 5) return Z_5;
    if (index == 6) return Z_6;
    if (index == 7) return Z_7;
    if (index == 8) return Z_8;
    if (index == 9) return Z_9;
    if (index == 10) return Z_10;
    if (index == 11) return Z_11;
    if (index == 12) return Z_12;
    if (index == 13) return Z_13;
    if (index == 14) return Z_14;
    if (index == 15) return Z_15;
    if (index == 16) return Z_16;
    if (index == 17) return Z_17;
    if (index == 18) return Z_18;
    if (index == 19) return Z_19;
    if (index == 20) return Z_20;
    if (index == 21) return Z_21;
    if (index == 22) return Z_22;
    if (index == 23) return Z_23;
    if (index == 24) return Z_24;
    if (index == 25) return Z_25;
    if (index == 26) return Z_26;
    if (index == 27) return Z_27;
    if (index == 28) return Z_28;
    if (index == 29) return Z_29;
    if (index == 30) return Z_30;
    if (index == 31) return Z_31;
    if (index == 32) return Z_32;
    revert DefaultZeroBadIndex();
  }

  /// @notice Initializes the LazyIMT
  /// @param self The LazyIMTData
  /// @param depth The depth of the tree
  function _init(LazyIMTData storage self, uint8 depth) internal {
    if (depth > MAX_DEPTH) {
      revert DepthTooLarge();
    }
    self.maxIndex = uint40((1 << depth) - 1);
    self.numberOfLeaves = 0;
  }

  /// @notice Returns the index for a given level and index
  /// @param level The level
  /// @param index The index
  /// @return The index for the element
  function _indexForElement(uint8 level, uint40 index) internal pure returns (uint40) {
    // store the elements sparsely
    return (uint40(level) << 32) - level + index;
  }

  /// @notice Inserts a leaf into the LazyIMT
  /// @param self The LazyIMTData
  /// @param leaf The leaf to insert
  function _insert(LazyIMTData storage self, uint256 leaf) internal returns (uint256) {
    uint40 index = self.numberOfLeaves;

    self.numberOfLeaves = index + 1;

    uint256 hash = leaf;

    for (uint8 i = 0; ; ) {
      self.elements[_indexForElement(i, index)] = hash;
      // it's a left element so we don't hash until there's a right element
      if (index & 1 == 0) break;
      uint40 elementIndex = _indexForElement(i, index - 1);
      hash = PoseidonT3.poseidon([self.elements[elementIndex], hash]);
      unchecked {
        index >>= 1;
        i++;
      }
    }

    return hash;
  }

  /// @notice Returns the root of the LazyIMT
  /// @param self The LazyIMTData
  /// @return The root of the LazyIMT
  function _root(LazyIMTData storage self) internal view returns (uint256) {
    // this will always short circuit if self.numberOfLeaves == 0
    uint40 numberOfLeaves = self.numberOfLeaves;
    // dynamically determine a depth
    uint8 depth = 1;
    while (uint40(1 << depth) < numberOfLeaves) {
      depth++;
    }
    return _root(self, numberOfLeaves, depth);
  }

  /// @notice Returns the root of the LazyIMT
  /// @dev Here it's assumed that the depth value is valid.
  /// If it is either 0 or > 2^8-1 this function will panic.
  /// @param self The LazyIMTData
  /// @param numberOfLeaves The number of leaves
  /// @param depth The depth of the tree
  /// @return The root of the LazyIMT
  function _root(LazyIMTData storage self, uint40 numberOfLeaves, uint8 depth) internal view returns (uint256) {
    if (depth > MAX_DEPTH) {
      revert DepthTooLarge();
    }
    // this should always short circuit if self.numberOfLeaves == 0
    if (numberOfLeaves == 0) return _defaultZero(depth);
    uint256[] memory levels = new uint256[](depth + 1);
    _levels(self, numberOfLeaves, depth, levels);
    return levels[depth];
  }

  /// @notice Updates the levels of the LazyIMT
  /// @param self The LazyIMTData
  /// @param numberOfLeaves The number of leaves
  /// @param depth The depth of the tree
  /// @param levels The levels of the tree
  function _levels(
    LazyIMTData storage self,
    uint40 numberOfLeaves,
    uint8 depth,
    uint256[] memory levels
  ) internal view {
    if (depth > MAX_DEPTH) {
      revert DepthTooLarge();
    }
    if (numberOfLeaves == 0) {
      revert NumberOfLeavesCannotBeZero();
    }

    // this should always short circuit if self.numberOfLeaves == 0
    uint40 index = numberOfLeaves - 1;

    if (index & 1 == 0) {
      levels[0] = self.elements[_indexForElement(0, index)];
    } else {
      levels[0] = _defaultZero(0);
    }

    for (uint8 i = 0; i < depth; ) {
      if (index & 1 == 0) {
        levels[i + 1] = PoseidonT3.poseidon([levels[i], _defaultZero(i)]);
      } else {
        uint256 levelCount = (numberOfLeaves) >> (i + 1);
        if (levelCount > index >> 1) {
          uint256 parent = self.elements[_indexForElement(i + 1, index >> 1)];
          levels[i + 1] = parent;
        } else {
          uint256 sibling = self.elements[_indexForElement(i, index - 1)];
          levels[i + 1] = PoseidonT3.poseidon([sibling, levels[i]]);
        }
      }
      unchecked {
        index >>= 1;
        i++;
      }
    }
  }
}

contracts/trees/LeanIMT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { PoseidonT3 } from "../crypto/PoseidonT3.sol";

struct LeanIMTData {
  // Tracks the current number of leaves in the tree.
  uint256 size;
  // Represents the current depth of the tree, which can increase as new leaves are inserted.
  uint256 depth;
  // A mapping from each level of the tree to the node value of the last even position at that level.
  // Used for efficient inserts, updates and root calculations.
  mapping(uint256 => uint256) sideNodes;
  // A mapping from leaf values to their respective indices in the tree.
  // This facilitates checks for leaf existence and retrieval of leaf positions.
  mapping(uint256 => uint256) leaves;
}

error WrongSiblingNodes();
error LeafGreaterThanSnarkScalarField();
error LeafCannotBeZero();
error LeafAlreadyExists();
error LeafDoesNotExist();

/// @title Lean Incremental binary Merkle tree.
/// @dev The LeanIMT is an optimized version of the BinaryIMT.
/// This implementation eliminates the use of zeroes, and make the tree depth dynamic.
/// When a node doesn't have the right child, instead of using a zero hash as in the BinaryIMT,
/// the node's value becomes that of its left child. Furthermore, rather than utilizing a static tree depth,
/// it is updated based on the number of leaves in the tree. This approach
/// results in the calculation of significantly fewer hashes, making the tree more efficient.
library InternalLeanIMT {
  /// @notice The scalar field
  uint256 internal constant SNARK_SCALAR_FIELD =
    21888242871839275222246405745257275088548364400416034343698204186575808495617;

  /// @dev Inserts a new leaf into the incremental merkle tree.
  /// The function ensures that the leaf is valid according to the
  /// constraints of the tree and then updates the tree's structure accordingly.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @param leaf: The value of the new leaf to be inserted into the tree.
  /// @return The new hash of the node after the leaf has been inserted.
  function _insert(LeanIMTData storage self, uint256 leaf) internal returns (uint256) {
    if (leaf >= SNARK_SCALAR_FIELD) {
      revert LeafGreaterThanSnarkScalarField();
    } else if (leaf == 0) {
      revert LeafCannotBeZero();
    } else if (_has(self, leaf)) {
      revert LeafAlreadyExists();
    }

    uint256 index = self.size;

    // Cache tree depth to optimize gas
    uint256 treeDepth = self.depth;

    // A new insertion can increase a tree's depth by at most 1,
    // and only if the number of leaves supported by the current
    // depth is less than the number of leaves to be supported after insertion.
    if (1 << treeDepth < index + 1) {
      ++treeDepth;
    }

    self.depth = treeDepth;

    uint256 node = leaf;

    for (uint256 level = 0; level < treeDepth; ) {
      if ((index >> level) & 1 == 1) {
        node = PoseidonT3.poseidon([self.sideNodes[level], node]);
      } else {
        self.sideNodes[level] = node;
      }

      unchecked {
        ++level;
      }
    }

    self.size = ++index;

    self.sideNodes[treeDepth] = node;
    self.leaves[leaf] = index;

    return node;
  }

  /// @dev Inserts many leaves into the incremental merkle tree.
  /// The function ensures that the leaves are valid according to the
  /// constraints of the tree and then updates the tree's structure accordingly.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @param leaves: The values of the new leaves to be inserted into the tree.
  /// @return The root after the leaves have been inserted.
  function _insertMany(LeanIMTData storage self, uint256[] calldata leaves) internal returns (uint256) {
    // Cache tree size to optimize gas
    uint256 treeSize = self.size;

    // Check that all the new values are correct to be added.
    for (uint256 i = 0; i < leaves.length; ) {
      if (leaves[i] >= SNARK_SCALAR_FIELD) {
        revert LeafGreaterThanSnarkScalarField();
      } else if (leaves[i] == 0) {
        revert LeafCannotBeZero();
      } else if (_has(self, leaves[i])) {
        revert LeafAlreadyExists();
      }

      self.leaves[leaves[i]] = treeSize + 1 + i;

      unchecked {
        ++i;
      }
    }

    // Array to save the nodes that will be used to create the next level of the tree.
    uint256[] memory currentLevelNewNodes;

    currentLevelNewNodes = leaves;

    // Cache tree depth to optimize gas
    uint256 treeDepth = self.depth;

    // Calculate the depth of the tree after adding the new values.
    // Unlike the 'insert' function, we need a while here as
    // N insertions can increase the tree's depth more than once.
    while (1 << treeDepth < treeSize + leaves.length) {
      ++treeDepth;
    }

    self.depth = treeDepth;

    // First index to change in every level.
    uint256 currentLevelStartIndex = treeSize;

    // Size of the level used to create the next level.
    uint256 currentLevelSize = treeSize + leaves.length;

    // The index where changes begin at the next level.
    uint256 nextLevelStartIndex = currentLevelStartIndex >> 1;

    // The size of the next level.
    uint256 nextLevelSize = ((currentLevelSize - 1) >> 1) + 1;

    for (uint256 level = 0; level < treeDepth; ) {
      // The number of nodes for the new level that will be created,
      // only the new values, not the entire level.
      uint256 numberOfNewNodes = nextLevelSize - nextLevelStartIndex;
      uint256[] memory nextLevelNewNodes = new uint256[](numberOfNewNodes);
      for (uint256 i = 0; i < numberOfNewNodes; ) {
        uint256 leftNode;

        // Assign the left node using the saved path or the position in the array.
        if ((i + nextLevelStartIndex) * 2 < currentLevelStartIndex) {
          leftNode = self.sideNodes[level];
        } else {
          leftNode = currentLevelNewNodes[(i + nextLevelStartIndex) * 2 - currentLevelStartIndex];
        }

        uint256 rightNode = 0;

        // Assign the right node if the value exists.
        if ((i + nextLevelStartIndex) * 2 + 1 < currentLevelSize) {
          rightNode = currentLevelNewNodes[(i + nextLevelStartIndex) * 2 + 1 - currentLevelStartIndex];
        }

        uint256 parentNode;

        // Assign the parent node.
        // If it has a right child the result will be the hash(leftNode, rightNode) if not,
        // it will be the leftNode.
        if (rightNode != 0) {
          parentNode = PoseidonT3.poseidon([leftNode, rightNode]);
        } else {
          parentNode = leftNode;
        }

        nextLevelNewNodes[i] = parentNode;

        unchecked {
          ++i;
        }
      }

      // Update the `sideNodes` variable.
      // If `currentLevelSize` is odd, the saved value will be the last value of the array
      // if it is even and there are more than 1 element in `currentLevelNewNodes`, the saved value
      // will be the value before the last one.
      // If it is even and there is only one element, there is no need to save anything because
      // the correct value for this level was already saved before.
      if (currentLevelSize & 1 == 1) {
        self.sideNodes[level] = currentLevelNewNodes[currentLevelNewNodes.length - 1];
      } else if (currentLevelNewNodes.length > 1) {
        self.sideNodes[level] = currentLevelNewNodes[currentLevelNewNodes.length - 2];
      }

      currentLevelStartIndex = nextLevelStartIndex;

      // Calculate the next level startIndex value.
      // It is the position of the parent node which is pos/2.
      nextLevelStartIndex >>= 1;

      // Update the next array that will be used to calculate the next level.
      currentLevelNewNodes = nextLevelNewNodes;

      currentLevelSize = nextLevelSize;

      // Calculate the size of the next level.
      // The size of the next level is (currentLevelSize - 1) / 2 + 1.
      nextLevelSize = ((nextLevelSize - 1) >> 1) + 1;

      unchecked {
        ++level;
      }
    }

    // Update tree size
    self.size = treeSize + leaves.length;

    // Update tree root
    self.sideNodes[treeDepth] = currentLevelNewNodes[0];

    return currentLevelNewNodes[0];
  }

  /// @dev Updates the value of an existing leaf and recalculates hashes
  /// to maintain tree integrity.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @param oldLeaf: The value of the leaf that is to be updated.
  /// @param newLeaf: The new value that will replace the oldLeaf in the tree.
  /// @param siblingNodes: An array of sibling nodes that are necessary to recalculate the path to the root.
  /// @return The new hash of the updated node after the leaf has been updated.
  function _update(
    LeanIMTData storage self,
    uint256 oldLeaf,
    uint256 newLeaf,
    uint256[] calldata siblingNodes
  ) internal returns (uint256) {
    if (newLeaf >= SNARK_SCALAR_FIELD) {
      revert LeafGreaterThanSnarkScalarField();
    } else if (!_has(self, oldLeaf)) {
      revert LeafDoesNotExist();
    } else if (_has(self, newLeaf)) {
      revert LeafAlreadyExists();
    }

    uint256 index = _indexOf(self, oldLeaf);
    uint256 node = newLeaf;
    uint256 oldRoot = oldLeaf;

    uint256 lastIndex = self.size - 1;
    uint256 i = 0;

    // Cache tree depth to optimize gas
    uint256 treeDepth = self.depth;

    for (uint256 level = 0; level < treeDepth; ) {
      if ((index >> level) & 1 == 1) {
        if (siblingNodes[i] >= SNARK_SCALAR_FIELD) {
          revert LeafGreaterThanSnarkScalarField();
        }

        node = PoseidonT3.poseidon([siblingNodes[i], node]);
        oldRoot = PoseidonT3.poseidon([siblingNodes[i], oldRoot]);

        unchecked {
          ++i;
        }
      } else {
        if (index >> level != lastIndex >> level) {
          if (siblingNodes[i] >= SNARK_SCALAR_FIELD) {
            revert LeafGreaterThanSnarkScalarField();
          }

          node = PoseidonT3.poseidon([node, siblingNodes[i]]);
          oldRoot = PoseidonT3.poseidon([oldRoot, siblingNodes[i]]);

          unchecked {
            ++i;
          }
        } else {
          self.sideNodes[i] = node;
        }
      }

      unchecked {
        ++level;
      }
    }

    if (oldRoot != _root(self)) {
      revert WrongSiblingNodes();
    }

    self.sideNodes[treeDepth] = node;

    if (newLeaf != 0) {
      self.leaves[newLeaf] = self.leaves[oldLeaf];
    }

    self.leaves[oldLeaf] = 0;

    return node;
  }

  /// @dev Removes a leaf from the tree by setting its value to zero.
  /// This function utilizes the update function to set the leaf's value
  /// to zero and update the tree's state accordingly.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @param oldLeaf: The value of the leaf to be removed.
  /// @param siblingNodes: An array of sibling nodes required for updating the path to the root after removal.
  /// @return The new root hash of the tree after the leaf has been removed.
  function _remove(
    LeanIMTData storage self,
    uint256 oldLeaf,
    uint256[] calldata siblingNodes
  ) internal returns (uint256) {
    return _update(self, oldLeaf, 0, siblingNodes);
  }

  /// @dev Checks if a leaf exists in the tree.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @param leaf: The value of the leaf to check for existence.
  /// @return A boolean value indicating whether the leaf exists in the tree.
  function _has(LeanIMTData storage self, uint256 leaf) internal view returns (bool) {
    return self.leaves[leaf] != 0;
  }

  /// @dev Retrieves the index of a given leaf in the tree.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @param leaf: The value of the leaf whose index is to be found.
  /// @return The index of the specified leaf within the tree. If the leaf is not present, the function
  /// reverts with a custom error.
  function _indexOf(LeanIMTData storage self, uint256 leaf) internal view returns (uint256) {
    if (self.leaves[leaf] == 0) {
      revert LeafDoesNotExist();
    }

    return self.leaves[leaf] - 1;
  }

  /// @dev Retrieves the root of the tree from the 'sideNodes' mapping using the
  /// current tree depth.
  /// @param self: A storage reference to the 'LeanIMTData' struct.
  /// @return The root hash of the tree.
  function _root(LeanIMTData storage self) internal view returns (uint256) {
    return self.sideNodes[self.depth];
  }
}

contracts/utilities/DomainObjs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title DomainObjs
/// @notice An utility contract that holds
/// a number of domain objects and functions
contract DomainObjs {
  /// @notice the length of a MACI message
  uint8 public constant MESSAGE_DATA_LENGTH = 10;

  /// @notice voting modes
  enum Mode {
    QV,
    NON_QV,
    FULL
  }

  /// @title Message
  /// @notice this struct represents a MACI message
  /// @dev msgType: 1 for vote message
  struct Message {
    uint256[MESSAGE_DATA_LENGTH] data;
  }

  /// @title PublicKey
  /// @notice A MACI public key
  struct PublicKey {
    uint256 x;
    uint256 y;
  }

  /// @title StateLeaf
  /// @notice A MACI state leaf
  /// @dev used to represent a user's state
  /// in the state Merkle tree
  struct StateLeaf {
    PublicKey publicKey;
    uint256 voiceCreditBalance;
  }
}

contracts/utilities/Params.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IBasePolicy } from "@excubiae/contracts/contracts/interfaces/IBasePolicy.sol";

import { IMACI } from "../interfaces/IMACI.sol";
import { IVerifier } from "../interfaces/IVerifier.sol";
import { IVerifyingKeysRegistry } from "../interfaces/IVerifyingKeysRegistry.sol";
import { IInitialVoiceCreditProxy } from "../interfaces/IInitialVoiceCreditProxy.sol";

/// @title Params
/// @notice This contracts contains a number of structures
/// which are to be passed as parameters to Poll contracts.
/// This way we can reduce the number of parameters
/// and avoid a stack too deep error during compilation.
contract Params {
  /// @notice A struct holding the depths of the merkle trees
  struct TreeDepths {
    uint8 tallyProcessingStateTreeDepth;
    uint8 voteOptionTreeDepth;
    uint8 stateTreeDepth;
  }

  /// @notice A struct holding the external contracts
  /// that are to be passed to a Poll contract on
  /// deployment
  struct ExtContracts {
    IMACI maci;
    IVerifier verifier;
    IVerifyingKeysRegistry verifyingKeysRegistry;
    IBasePolicy policy;
    IInitialVoiceCreditProxy initialVoiceCreditProxy;
  }
}

contracts/utilities/Utilities.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { DomainObjs } from "./DomainObjs.sol";
import { Hasher } from "../crypto/Hasher.sol";
import { SnarkConstants } from "../crypto/SnarkConstants.sol";

/// @title Utilities
/// @notice An utility contract that can be used to:
/// * hash a state leaf
/// * pad and hash a MACI message
/// * hash a MACI message and an encryption public key
contract Utilities is SnarkConstants, DomainObjs, Hasher {
  /// @notice custom errors
  error InvalidMessage();

  /// @notice An utility function used to hash a state leaf
  /// @param _stateLeaf the state leaf to be hashed
  /// @return ciphertext The hash of the state leaf
  function hashStateLeaf(StateLeaf memory _stateLeaf) public pure returns (uint256 ciphertext) {
    uint256[3] memory plaintext;
    plaintext[0] = _stateLeaf.publicKey.x;
    plaintext[1] = _stateLeaf.publicKey.y;
    plaintext[2] = _stateLeaf.voiceCreditBalance;

    ciphertext = hash3(plaintext);
  }

  /// @notice An utility function used to pad and hash a MACI message
  /// @param dataToPad the data to be padded
  /// @return message The padded message
  /// @return padKey The padding public key
  /// @return msgHash The hash of the padded message and encryption key
  function padAndHashMessage(
    uint256[2] memory dataToPad
  ) public pure returns (Message memory message, PublicKey memory padKey, uint256 msgHash) {
    // add data and pad it to 10 elements (automatically cause it's the default value)
    uint256[10] memory dat;
    dat[0] = dataToPad[0];
    dat[1] = dataToPad[1];

    padKey = PublicKey(PAD_PUBLIC_KEY_X, PAD_PUBLIC_KEY_Y);
    message = Message({ data: dat });
    msgHash = hashMessageAndPublicKey(message, padKey);
  }

  /// @notice An utility function used to hash a MACI message and an encryption public key
  /// @param _message the message to be hashed
  /// @param _encryptionPublicKey the encryption public key to be hashed
  /// @return msgHash The hash of the message and the encryption public key
  function hashMessageAndPublicKey(
    Message memory _message,
    PublicKey memory _encryptionPublicKey
  ) public pure returns (uint256 msgHash) {
    if (_message.data.length != 10) {
      revert InvalidMessage();
    }

    uint256[5] memory n;
    n[0] = _message.data[0];
    n[1] = _message.data[1];
    n[2] = _message.data[2];
    n[3] = _message.data[3];
    n[4] = _message.data[4];

    uint256[5] memory m;
    m[0] = _message.data[5];
    m[1] = _message.data[6];
    m[2] = _message.data[7];
    m[3] = _message.data[8];
    m[4] = _message.data[9];

    msgHash = hash4([hash5(n), hash5(m), _encryptionPublicKey.x, _encryptionPublicKey.y]);
  }
}

contracts/VerifyingKeysRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

import { SnarkCommon } from "./crypto/SnarkCommon.sol";
import { IVerifyingKeysRegistry } from "./interfaces/IVerifyingKeysRegistry.sol";
import { DomainObjs } from "./utilities/DomainObjs.sol";

/// @title VerifyingKeysRegistry
/// @notice Stores verifying keys for the circuits.
/// Each circuit has a signature which is its compile-time constants represented
/// as a uint256.
contract VerifyingKeysRegistry is Ownable, DomainObjs, SnarkCommon, IVerifyingKeysRegistry {
  mapping(Mode => mapping(uint256 => VerifyingKey)) internal processVerifyingKeys;
  mapping(Mode => mapping(uint256 => bool)) internal processVerifyingKeysSet;

  mapping(Mode => mapping(uint256 => VerifyingKey)) internal tallyVerifyingKeys;
  mapping(Mode => mapping(uint256 => bool)) internal tallyVerifyingKeysSet;

  mapping(uint256 => VerifyingKey) internal pollJoiningVerifyingKeys;
  mapping(uint256 => bool) internal pollJoiningVerifyingKeysSet;

  mapping(uint256 => VerifyingKey) internal pollJoinedVerifyingKeys;
  mapping(uint256 => bool) internal pollJoinedVerifyingKeysSet;

  event PollJoiningVerifyingKeySet(uint256 _signature);
  event PollJoinedVerifyingKeySet(uint256 _signature);
  event ProcessVerifyingKeySet(uint256 _signature, Mode _mode);
  event TallyVerifyingKeySet(uint256 _signature, Mode _mode);

  error VerifyingKeyAlreadySet();
  error VerifyingKeyNotSet();
  error InvalidKeysParams();

  /// @notice Create a new instance of the VerifyingKeysRegistry contract
  // solhint-disable-next-line no-empty-blocks
  constructor(address _initialOwner) payable Ownable(_initialOwner) {}

  /// @notice Check if the poll joining verifying key is set
  /// @param _signature The signature
  /// @return isSet whether the verifying key is set
  function isPollJoiningVerifyingKeySet(uint256 _signature) public view returns (bool isSet) {
    isSet = pollJoiningVerifyingKeysSet[_signature];
  }

  /// @notice Check if the poll joined verifying key is set
  /// @param _signature The signature
  /// @return isSet whether the verifying key is set
  function isPollJoinedVerifyingKeySet(uint256 _signature) public view returns (bool isSet) {
    isSet = pollJoinedVerifyingKeysSet[_signature];
  }

  /// @notice Check if the process verifying key is set
  /// @param _signature The signature
  /// @param _mode QV, Non-QV, Full
  /// @return isSet whether the verifying key is set
  function isProcessVerifyingKeySet(uint256 _signature, Mode _mode) public view returns (bool isSet) {
    isSet = processVerifyingKeysSet[_mode][_signature];
  }

  /// @notice Check if the tally verifying key is set
  /// @param _signature The signature
  /// @param _mode QV, Non-QV, Full
  /// @return isSet whether the verifying key is set
  function isTallyVerifyingKeySet(uint256 _signature, Mode _mode) public view returns (bool isSet) {
    isSet = tallyVerifyingKeysSet[_mode][_signature];
  }

  /// @notice generate the signature for the poll joining verifying key
  /// @param _stateTreeDepth The state tree depth
  function generatePollJoiningVerifyingKeySignature(uint256 _stateTreeDepth) public pure returns (uint256 signature) {
    signature = (_stateTreeDepth << 64);
  }

  /// @notice generate the signature for the poll joined verifying key
  /// @param _stateTreeDepth The state tree depth
  function generatePollJoinedVerifyingKeySignature(uint256 _stateTreeDepth) public pure returns (uint256 signature) {
    signature = (_stateTreeDepth << 128);
  }

  /// @notice generate the signature for the process verifying key
  /// @param _stateTreeDepth The state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _messageBatchSize The message batch size
  function generateProcessVerifyingKeySignature(
    uint256 _stateTreeDepth,
    uint256 _voteOptionTreeDepth,
    uint8 _messageBatchSize
  ) public pure returns (uint256 signature) {
    signature = (_messageBatchSize << 128) + (_stateTreeDepth << 64) + _voteOptionTreeDepth;
  }

  /// @notice generate the signature for the tally verifying key
  /// @param _stateTreeDepth The state tree depth
  /// @param _intStateTreeDepth The intermediate state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @return signature The signature
  function generateTallyVerifyingKeySignature(
    uint256 _stateTreeDepth,
    uint256 _intStateTreeDepth,
    uint256 _voteOptionTreeDepth
  ) public pure returns (uint256 signature) {
    signature = (_stateTreeDepth << 128) + (_intStateTreeDepth << 64) + _voteOptionTreeDepth;
  }

  /// @notice Set the process and tally verifying keys for a certain combination
  /// of parameters and modes
  /// @param _args The verifying keys arguments
  function setVerifyingKeysBatch(SetVerifyingKeysBatchArgs calldata _args) public onlyOwner {
    if (
      _args.modes.length != _args.processVerifyingKeys.length || _args.modes.length != _args.tallyVerifyingKeys.length
    ) {
      revert InvalidKeysParams();
    }

    uint256 length = _args.modes.length;

    setPollJoiningVerifyingKey(_args.pollStateTreeDepth, _args.pollJoiningVerifyingKey);
    setPollJoinedVerifyingKey(_args.pollStateTreeDepth, _args.pollJoinedVerifyingKey);

    for (uint256 index = 0; index < length; ) {
      setVerifyingKeys(
        _args.stateTreeDepth,
        _args.tallyProcessingStateTreeDepth,
        _args.voteOptionTreeDepth,
        _args.messageBatchSize,
        _args.modes[index],
        _args.processVerifyingKeys[index],
        _args.tallyVerifyingKeys[index]
      );

      unchecked {
        index++;
      }
    }
  }

  /// @notice Set the process and tally verifying keys for a certain combination
  /// @param _stateTreeDepth The state tree depth
  /// @param _intStateTreeDepth The intermediate state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _messageBatchSize The message batch size
  /// @param _mode QV, Non-QV, Full
  /// @param _processVerifyingKey The process verifying key
  /// @param _tallyVerifyingKey The tally verifying key
  function setVerifyingKeys(
    uint256 _stateTreeDepth,
    uint256 _intStateTreeDepth,
    uint256 _voteOptionTreeDepth,
    uint8 _messageBatchSize,
    Mode _mode,
    VerifyingKey calldata _processVerifyingKey,
    VerifyingKey calldata _tallyVerifyingKey
  ) public onlyOwner {
    setProcessVerifyingKey(_stateTreeDepth, _voteOptionTreeDepth, _messageBatchSize, _mode, _processVerifyingKey);
    setTallyVerifyingKey(_stateTreeDepth, _intStateTreeDepth, _voteOptionTreeDepth, _mode, _tallyVerifyingKey);
  }

  /// @notice Set the process verifying key for a certain combination of parameters
  /// @param _stateTreeDepth The state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _messageBatchSize The message batch size
  /// @param _mode QV, Non-QV, Full
  /// @param _processVerifyingKey The process verifying key
  function setProcessVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _voteOptionTreeDepth,
    uint8 _messageBatchSize,
    Mode _mode,
    VerifyingKey calldata _processVerifyingKey
  ) public onlyOwner {
    uint256 processVerifyingKeySignature = generateProcessVerifyingKeySignature(
      _stateTreeDepth,
      _voteOptionTreeDepth,
      _messageBatchSize
    );

    if (processVerifyingKeysSet[_mode][processVerifyingKeySignature]) {
      revert VerifyingKeyAlreadySet();
    }

    VerifyingKey storage processVerifyingKey = processVerifyingKeys[_mode][processVerifyingKeySignature];
    processVerifyingKey.alpha1 = _processVerifyingKey.alpha1;
    processVerifyingKey.beta2 = _processVerifyingKey.beta2;
    processVerifyingKey.gamma2 = _processVerifyingKey.gamma2;
    processVerifyingKey.delta2 = _processVerifyingKey.delta2;

    uint256 processIcLength = _processVerifyingKey.ic.length;
    for (uint256 i = 0; i < processIcLength; ) {
      processVerifyingKey.ic.push(_processVerifyingKey.ic[i]);

      unchecked {
        i++;
      }
    }

    processVerifyingKeysSet[_mode][processVerifyingKeySignature] = true;

    emit ProcessVerifyingKeySet(processVerifyingKeySignature, _mode);
  }

  /// @notice Set the tally verifying key for a certain combination of parameters
  /// @param _stateTreeDepth The state tree depth
  /// @param _intStateTreeDepth The intermediate state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _mode QV, Non-QV, Full
  /// @param _tallyVerifyingKey The tally verifying key
  function setTallyVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _intStateTreeDepth,
    uint256 _voteOptionTreeDepth,
    Mode _mode,
    VerifyingKey calldata _tallyVerifyingKey
  ) public onlyOwner {
    uint256 tallyVerifyingKeySignature = generateTallyVerifyingKeySignature(
      _stateTreeDepth,
      _intStateTreeDepth,
      _voteOptionTreeDepth
    );

    if (tallyVerifyingKeysSet[_mode][tallyVerifyingKeySignature]) {
      revert VerifyingKeyAlreadySet();
    }

    VerifyingKey storage tallyVerifyingKey = tallyVerifyingKeys[_mode][tallyVerifyingKeySignature];
    tallyVerifyingKey.alpha1 = _tallyVerifyingKey.alpha1;
    tallyVerifyingKey.beta2 = _tallyVerifyingKey.beta2;
    tallyVerifyingKey.gamma2 = _tallyVerifyingKey.gamma2;
    tallyVerifyingKey.delta2 = _tallyVerifyingKey.delta2;

    uint256 tallyIcLength = _tallyVerifyingKey.ic.length;
    for (uint256 i = 0; i < tallyIcLength; ) {
      tallyVerifyingKey.ic.push(_tallyVerifyingKey.ic[i]);

      unchecked {
        i++;
      }
    }

    tallyVerifyingKeysSet[_mode][tallyVerifyingKeySignature] = true;

    emit TallyVerifyingKeySet(tallyVerifyingKeySignature, _mode);
  }

  /// @notice Set the poll joining verifying key for a certain combination of parameters
  /// @param _stateTreeDepth The state tree depth
  /// @param _pollJoiningVerifyingKey The poll joining verifying key
  function setPollJoiningVerifyingKey(
    uint256 _stateTreeDepth,
    VerifyingKey calldata _pollJoiningVerifyingKey
  ) public onlyOwner {
    uint256 pollJoiningVerifyingKeySignature = generatePollJoiningVerifyingKeySignature(_stateTreeDepth);

    if (pollJoiningVerifyingKeysSet[pollJoiningVerifyingKeySignature]) {
      revert VerifyingKeyAlreadySet();
    }

    VerifyingKey storage pollJoiningVerifyingKey = pollJoiningVerifyingKeys[pollJoiningVerifyingKeySignature];
    pollJoiningVerifyingKey.alpha1 = _pollJoiningVerifyingKey.alpha1;
    pollJoiningVerifyingKey.beta2 = _pollJoiningVerifyingKey.beta2;
    pollJoiningVerifyingKey.gamma2 = _pollJoiningVerifyingKey.gamma2;
    pollJoiningVerifyingKey.delta2 = _pollJoiningVerifyingKey.delta2;

    uint256 pollIcLength = _pollJoiningVerifyingKey.ic.length;
    for (uint256 i = 0; i < pollIcLength; ) {
      pollJoiningVerifyingKey.ic.push(_pollJoiningVerifyingKey.ic[i]);

      unchecked {
        i++;
      }
    }

    pollJoiningVerifyingKeysSet[pollJoiningVerifyingKeySignature] = true;

    emit PollJoiningVerifyingKeySet(pollJoiningVerifyingKeySignature);
  }

  /// @notice Set the poll joined verifying key for a certain combination of parameters
  /// @param _stateTreeDepth The state tree depth
  /// @param _pollJoinedVerifyingSignature The poll joined verifying key
  function setPollJoinedVerifyingKey(
    uint256 _stateTreeDepth,
    VerifyingKey calldata _pollJoinedVerifyingSignature
  ) public onlyOwner {
    uint256 pollJoinedVerifyingKeySignature = generatePollJoinedVerifyingKeySignature(_stateTreeDepth);

    if (pollJoinedVerifyingKeysSet[pollJoinedVerifyingKeySignature]) {
      revert VerifyingKeyAlreadySet();
    }

    VerifyingKey storage pollJoinedVerifyingKey = pollJoinedVerifyingKeys[pollJoinedVerifyingKeySignature];
    pollJoinedVerifyingKey.alpha1 = _pollJoinedVerifyingSignature.alpha1;
    pollJoinedVerifyingKey.beta2 = _pollJoinedVerifyingSignature.beta2;
    pollJoinedVerifyingKey.gamma2 = _pollJoinedVerifyingSignature.gamma2;
    pollJoinedVerifyingKey.delta2 = _pollJoinedVerifyingSignature.delta2;

    uint256 pollIcLength = _pollJoinedVerifyingSignature.ic.length;
    for (uint256 i = 0; i < pollIcLength; ) {
      pollJoinedVerifyingKey.ic.push(_pollJoinedVerifyingSignature.ic[i]);

      unchecked {
        i++;
      }
    }

    pollJoinedVerifyingKeysSet[pollJoinedVerifyingKeySignature] = true;

    emit PollJoinedVerifyingKeySet(pollJoinedVerifyingKeySignature);
  }

  /// @notice Check if the process verifying key is set
  /// @param _stateTreeDepth The state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _messageBatchSize The message batch size
  /// @param _mode QV, Non-QV, Full
  /// @return isSet whether the verifying key is set
  function hasProcessVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _voteOptionTreeDepth,
    uint8 _messageBatchSize,
    Mode _mode
  ) public view returns (bool isSet) {
    uint256 signature = generateProcessVerifyingKeySignature(_stateTreeDepth, _voteOptionTreeDepth, _messageBatchSize);
    isSet = processVerifyingKeysSet[_mode][signature];
  }

  /// @notice Get the process verifying key by signature
  /// @param _signature The signature
  /// @param _mode QV, Non-QV, Full
  /// @return verifyingKey The verifying key
  function getProcessVerifyingKeyBySignature(
    uint256 _signature,
    Mode _mode
  ) public view returns (VerifyingKey memory verifyingKey) {
    if (!processVerifyingKeysSet[_mode][_signature]) {
      revert VerifyingKeyNotSet();
    }

    verifyingKey = processVerifyingKeys[_mode][_signature];
  }

  /// @inheritdoc IVerifyingKeysRegistry
  function getProcessVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _voteOptionTreeDepth,
    uint8 _messageBatchSize,
    Mode _mode
  ) public view returns (VerifyingKey memory verifyingKey) {
    uint256 signature = generateProcessVerifyingKeySignature(_stateTreeDepth, _voteOptionTreeDepth, _messageBatchSize);

    verifyingKey = getProcessVerifyingKeyBySignature(signature, _mode);
  }

  /// @notice Check if the tally verifying key is set
  /// @param _stateTreeDepth The state tree depth
  /// @param _intStateTreeDepth The intermediate state tree depth
  /// @param _voteOptionTreeDepth The vote option tree depth
  /// @param _mode QV, Non-QV, Full
  /// @return isSet whether the verifying key is set
  function hasTallyVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _intStateTreeDepth,
    uint256 _voteOptionTreeDepth,
    Mode _mode
  ) public view returns (bool isSet) {
    uint256 signature = generateTallyVerifyingKeySignature(_stateTreeDepth, _intStateTreeDepth, _voteOptionTreeDepth);

    isSet = tallyVerifyingKeysSet[_mode][signature];
  }

  /// @notice Get the tally verifying key by signature
  /// @param _signature The signature
  /// @param _mode QV, Non-QV, Full
  /// @return verifyingKey The verifying key
  function getTallyVerifyingKeyBySignature(
    uint256 _signature,
    Mode _mode
  ) public view returns (VerifyingKey memory verifyingKey) {
    if (!tallyVerifyingKeysSet[_mode][_signature]) {
      revert VerifyingKeyNotSet();
    }

    verifyingKey = tallyVerifyingKeys[_mode][_signature];
  }

  /// @inheritdoc IVerifyingKeysRegistry
  function getTallyVerifyingKey(
    uint256 _stateTreeDepth,
    uint256 _intStateTreeDepth,
    uint256 _voteOptionTreeDepth,
    Mode _mode
  ) public view returns (VerifyingKey memory verifyingKey) {
    uint256 signature = generateTallyVerifyingKeySignature(_stateTreeDepth, _intStateTreeDepth, _voteOptionTreeDepth);

    verifyingKey = getTallyVerifyingKeyBySignature(signature, _mode);
  }

  /// @notice Get the poll joining verifying key by signature
  /// @param _signature The signature
  /// @return verifyingKey The verifying key
  function getPollJoiningVerifyingKeyBySignature(
    uint256 _signature
  ) public view returns (VerifyingKey memory verifyingKey) {
    if (!pollJoiningVerifyingKeysSet[_signature]) revert VerifyingKeyNotSet();

    verifyingKey = pollJoiningVerifyingKeys[_signature];
  }

  /// @notice Get the poll joined verifying key by signature
  /// @param _signature The signature
  /// @return verifyingKey The verifying key
  function getPollJoinedVerifyingKeyBySignature(
    uint256 _signature
  ) public view returns (VerifyingKey memory verifyingKey) {
    if (!pollJoinedVerifyingKeysSet[_signature]) revert VerifyingKeyNotSet();

    verifyingKey = pollJoinedVerifyingKeys[_signature];
  }

  /// @inheritdoc IVerifyingKeysRegistry
  function getPollJoiningVerifyingKey(uint256 _stateTreeDepth) public view returns (VerifyingKey memory verifyingKey) {
    uint256 signature = generatePollJoiningVerifyingKeySignature(_stateTreeDepth);

    verifyingKey = getPollJoiningVerifyingKeyBySignature(signature);
  }

  /// @inheritdoc IVerifyingKeysRegistry
  function getPollJoinedVerifyingKey(uint256 _stateTreeDepth) public view returns (VerifyingKey memory verifyingKey) {
    uint256 signature = generatePollJoinedVerifyingKeySignature(_stateTreeDepth);

    verifyingKey = getPollJoinedVerifyingKeyBySignature(signature);
  }
}

